<script>
(() => {
  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');
  const fpsEl = document.getElementById('fps');

  // --- Canvas sizing ---
  const SIZE = 600;
  canvas.width = SIZE;
  canvas.height = SIZE;

  // --- Cube geometry (unit cube centered at origin) ---
  const V = [
    [-1, -1, -1],  // 0: back-bottom-left
    [ 1, -1, -1],  // 1: back-bottom-right
    [ 1,  1, -1],  // 2: back-top-right
    [-1,  1, -1],  // 3: back-top-left
    [-1, -1,  1],  // 4: front-bottom-left
    [ 1, -1,  1],  // 5: front-bottom-right
    [ 1,  1,  1],  // 6: front-top-right
    [-1,  1,  1],  // 7: front-top-left
  ];

  // 6 faces, each split into 2 triangles (12 triangles total)
  // Face vertices: [a,b,c,d] -> triangles [a,b,c] and [a,c,d]
  const FACES = [
    { verts: [0, 1, 2, 3], normal: [0, 0, -1] },  // back
    { verts: [5, 4, 7, 6], normal: [0, 0,  1] },  // front
    { verts: [4, 0, 3, 7], normal: [-1, 0, 0] },  // left
    { verts: [1, 5, 6, 2], normal: [ 1, 0, 0] },  // right
    { verts: [3, 2, 6, 7], normal: [0, -1, 0] },  // top
    { verts: [4, 5, 1, 0], normal: [0,  1, 0] },  // bottom
  ];

  // Precompute triangle list: each entry = [faceIndex, triIndex, v0, v1, v2]
  const TRIANGLES = [];
  for (let f = 0; f < FACES.length; f++) {
    const { verts } = FACES[f];
    TRIANGLES.push({ face: f, tri: 0, v: [verts[0], verts[1], verts[2]] });
    TRIANGLES.push({ face: f, tri: 1, v: [verts[0], verts[2], verts[3]] });
  }

  // --- State ---
  let angleX = 0;
  let angleY = 0;
  let angleZ = 0;
  let paused = false;
  let wireframe = false;
  let lightAngle = 0;

  // --- Math helpers ---
  function rotX(v, a) {
    const c = Math.cos(a), s = Math.sin(a);
    return [v[0], v[1]*c - v[2]*s, v[1]*s + v[2]*c];
  }
  function rotY(v, a) {
    const c = Math.cos(a), s = Math.sin(a);
    return [v[0]*c + v[2]*s, v[1], -v[0]*s + v[2]*c];
  }
  function rotZ(v, a) {
    const c = Math.cos(a), s = Math.sin(a);
    return [v[0]*c - v[1]*s, v[0]*s + v[1]*c, v[2]];
  }

  function transformVertex(v) {
    let p = [...v];
    p = rotX(p, angleX);
    p = rotY(p, angleY);
    p = rotZ(p, angleZ);
    return p;
  }

  // Perspective projection
  const FOV = 400;
  const Z_NEAR = 2;
  function project(p) {
    const z = p[2] + 4; // push cube back from camera
    const scale = FOV / (z + Z_NEAR);
    return [p[0] * scale + SIZE / 2, -p[1] * scale + SIZE / 2, z];
  }

  // --- Backface culling: compute signed area in screen space ---
  function isFrontFacing(p0, p1, p2) {
    return ((p1[0] - p0[0]) * (p2[1] - p0[1]) - (p1[1] - p0[1]) * (p2[0] - p0[0])) > 0;
  }

  // --- Barycentric interpolation ---
  function barycentric(px, py, ax, ay, bx, by, cx, cy) {
    const denom = (by - cy) * (ax - cx) + (cx - bx) * (ay - cy);
    if (Math.abs(denom) < 1e-10) return null;
    const w0 = ((by - cy) * (px - cx) + (cx - bx) * (py - cy)) / denom;
    const w1 = ((cy - ay) * (px - cx) + (ax - cx) * (py - cy)) / denom;
    const w2 = 1 - w0 - w1;
    return { w0, w1, w2 };
  }

  // Edge function test for bounding box rasterization
  function edge(ax, ay, bx, by, cx, cy) {
    return (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
  }

  function pointInTriangle(px, py, ax, ay, bx, by, cx, cy) {
    const e0 = edge(ax, ay, bx, by, px, py);
    const e1 = edge(bx, by, cx, cy, px, py);
    const e2 = edge(cx, cy, ax, ay, px, py);
    return (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0);
  }

  // --- Lambert lighting ---
  function normalize(v) {
    const len = Math.sqrt(v[0]*v[0] + v[1]*v[1] + v[2]*v[2]);
    return len > 0 ? [v[0]/len, v[1]/len, v[2]/len] : [0, 0, 0];
  }

  function dot(a, b) {
    return a[0]*b[0] + a[1]*b[1] + a[2]*b[2];
  }

  function computeLightDir() {
    // Moving light source: orbits around the scene
    const lx = Math.cos(lightAngle) * 3;
    const lz = Math.sin(lightAngle) * 3;
    const ly = Math.sin(lightAngle * 0.7) * 2 + 1;
    return normalize([lx, ly, lz]);
  }

  // Face normals in world space (pre-rotated for the current frame)
  // We compute them from the rotated face vertices
  function computeFaceNormal(p0, p1, p2) {
    const ax = p1[0] - p0[0], ay = p1[1] - p0[1], az = p1[2] - p0[2];
    const bx = p2[0] - p0[0], by = p2[1] - p0[1], bz = p2[2] - p0[2];
    return normalize([
      ay * bz - az * by,
      az * bx - ax * bz,
      ax * by - ay * bx
    ]);
  }

  function vertexColor(normal, lightDir) {
    const intensity = Math.max(0, dot(normal, lightDir));
    // Ambient + diffuse: warm color palette
    const ambient = 0.25;
    const total = ambient + (1 - ambient) * intensity;
    // Base color: warm orange/amber
    const r = Math.min(1, 0.55 * total + 0.45);
    const g = Math.min(1, 0.35 * total + 0.30);
    const b = Math.min(1, 0.15 * total + 0.20);
    return [r, g, b];
  }

  // --- Frame rendering ---
  let lastTime = performance.now();
  let frameCount = 0;
  let fpsDisplay = 0;
  let fpsTimer = 0;

  function render(now) {
    // FPS tracking
    frameCount++;
    if (now - fpsTimer > 500) {
      fpsDisplay = Math.round(frameCount / ((now - fpsTimer) / 1000));
      fpsTimer = now;
      frameCount = 0;
      fpsEl.textContent = fpsDisplay;
    }

    // Clear
    ctx.fillStyle = '#0d0d1a';
    ctx.fillRect(0, 0, SIZE, SIZE);

    // Update light position
    lightAngle += 0.02;
    const lightDir = computeLightDir();

    // Advance rotation if not paused
    if (!paused) {
      angleX += 0.015;
      angleY += 0.02;
      angleZ += 0.008;
    }

    // Transform all vertices once per frame
    const rotated = V.map(v => transformVertex(v));

    // Project vertices
    const projected = rotated.map(p => project(p));

    // Prepare scanline buffer for Gouraud shading
    // We'll draw each visible triangle with interpolated vertex colors
    const imageData = ctx.getImageData(0, 0, SIZE, SIZE);
    const pixels = imageData.data;

    // For each triangle, rasterize with Gouraud shading
    for (const tri of TRIANGLES) {
      const vIdx = tri.v;
      const p0 = projected[vIdx[0]];
      const p1 = projected[vIdx[1]];
      const p2 = projected[vIdx[2]];

