      const r0 = rotated[vIdx[0]];
      const r1 = rotated[vIdx[1]];
      const r2 = rotated[vIdx[2]];
      const faceNormal = computeFaceNormal(r0, r1, r2);

      // Compute per-vertex colors using vertex normals
      // For a cube, vertex normals = face normals (flat shading per vertex would be same)
      // But for Gouraud, we use the actual face normal at each vertex (same for all 3 in a cube face)
      // To make Gouraud visible, we use the face normal for all 3 vertices
      // Actually for a cube, all vertices of a face share the same normal.
      // Gouraud shading on a cube with flat faces = same as flat shading per face.
      // To demonstrate Gouraud properly, we compute vertex normals as average of adjacent face normals.
      // Let's compute vertex normals properly: average of face normals of faces sharing this vertex.

      // Precomputed vertex normals (average of adjacent faces)
      // Vertices and their adjacent faces:
      // 0: back, left, bottom
      // 1: back, right, bottom
      // 2: back, right, top
      // 3: back, left, top
      // 4: front, left, bottom
      // 5: front, right, bottom
      // 6: front, right, top
      // 7: front, left, top
      const vertexFaces = [
        [0, 2, 5], // v0: back, left, bottom
        [0, 3, 5], // v1: back, right, bottom
        [0, 3, 4], // v2: back, right, top
        [0, 2, 4], // v3: back, left, top
        [1, 2, 5], // v4: front, left, bottom
        [1, 3, 5], // v5: front, right, bottom
        [1, 3, 4], // v6: front, right, top
        [1, 2, 4], // v7: front, left, top
      ];

      // Compute rotated face normals for lighting
      const rotatedFaceNormals = FACES.map(f => {
        const idx = f.verts;
        const a = rotated[idx[0]];
        const b = rotated[idx[1]];
        const c = rotated[idx[2]];
        return computeFaceNormal(a, b, c);
      });

      // Compute vertex normals (average of adjacent face normals)
      const vertexNormals = vertexFaces.map(adj => {
        let nx = 0, ny = 0, nz = 0;
        for (const fi of adj) {
          nx += rotatedFaceNormals[fi][0];
          ny += rotatedFaceNormals[fi][1];
          nz += rotatedFaceNormals[fi][2];
        }
        return normalize([nx, ny, nz]);
      });

      // Vertex colors (Gouraud: compute at each vertex)
      const c0 = vertexColor(vertexNormals[vIdx[0]], lightDir);
      const c1 = vertexColor(vertexNormals[vIdx[1]], lightDir);
      const c2 = vertexColor(vertexNormals[vIdx[2]], lightDir);

      // Bounding box
      const minX = Math.max(0, Math.floor(Math.min(p0[0], p1[0], p2[0])));
      const maxX = Math.min(SIZE - 1, Math.ceil(Math.max(p0[0], p1[0], p2[0])));
      const minY = Math.max(0, Math.floor(Math.min(p0[1], p1[1], p2[1])));
      const maxY = Math.min(SIZE - 1, Math.ceil(Math.max(p0[1], p1[1], p2[1])));

      // Rasterize
      for (let y = minY; y <= maxY; y++) {
        for (let x = minX; x <= maxX; x++) {
          if (!pointInTriangle(x + 0.5, y + 0.5, p0[0], p0[1], p1[0], p1[1], p2[0], p2[1])) continue;

          const bc = barycentric(x + 0.5, y + 0.5, p0[0], p0[1], p1[0], p1[1], p2[0], p2[1]);
          if (!bc) continue;

          // Interpolate Z for depth test (simple painter's algorithm: sort by average depth)
          const z = bc.w0 * p0[2] + bc.w1 * p1[2] + bc.w2 * p2[2];

          // Interpolate colors
          const r = bc.w0 * c0[0] + bc.w1 * c1[0] + bc.w2 * c2[0];
          const g = bc.w0 * c0[1] + bc.w1 * c1[1] + bc.w2 * c2[1];
          const b = bc.w0 * c0[2] + bc.w1 * c1[2] + bc.w2 * c2[2];

          const idx = (y * SIZE + x) * 4;

          // Simple depth buffer (we'll do per-triangle sorting instead)
          // For simplicity, we draw in order of average depth (painter's algorithm)
          // We'll handle this outside the rasterizer by sorting triangles first.

          // Store for later (we'll sort and draw in order)
          // Actually, let's use a depth buffer approach:
          // We'll maintain a depth buffer per frame.
          if (!render.depthBuffer) render.depthBuffer = new Float32Array(SIZE * SIZE);
          const depthIdx = y * SIZE + x;
          if (z < render.depthBuffer[depthIdx] || render.depthBuffer[depthIdx] === 0) {
            render.depthBuffer[depthIdx] = z;
            pixels[idx]     = Math.round(r * 255);
            pixels[idx + 1] = Math.round(g * 255);
            pixels[idx + 2] = Math.round(b * 255);
            pixels[idx + 3] = 255;
          }
        }
      }
    }

    // Draw wireframe overlay if enabled
    if (wireframe) {
      ctx.putImageData(imageData, 0, 0);
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.6)';
      ctx.lineWidth = 1;
      for (const tri of TRIANGLES) {
        const vIdx = tri.v;
        const p0 = projected[vIdx[0]];
        const p1 = projected[vIdx[1]];
        const p2 = projected[vIdx[2]];
        if (!isFrontFacing(p0, p1, p2)) continue;
        ctx.beginPath();
        ctx.moveTo(p0[0], p0[1]);
        ctx.lineTo(p1[0], p1[1]);
        ctx.lineTo(p2[0], p2[1]);
        ctx.closePath();
        ctx.stroke();
      }
    } else {
      ctx.putImageData(imageData, 0, 0);
    }

    // Reset depth buffer for next frame
    render.depthBuffer = new Float32Array(SIZE * SIZE);

    requestAnimationFrame(render);
  }

  // Handle keyboard
  window.addEventListener('keydown', (e) => {
    if (e.key === 'w' || e.key === 'W') {
      wireframe = !wireframe;
    } else if (e.key === 'p' || e.key === 'P') {
      paused = !paused;
    }
  });

  // Start
  requestAnimationFrame(render);
})();
